// NutriScanner — Input Validator, Business Rule Guard, and Adaptive Batching
const body = $input.item.json.body || $input.item.json;
const binaryData = $input.item.binary || {};
const mode = body.mode || (Object.keys(binaryData).length > 0 ? 'photo' : 'text');

// Strict Product Rule: Max 4 photos per session
const MAX_PRODUCT_IMAGES = 4;
// Provider Implementation Constraint: Adaptive batching limit (e.g. 3 images per request on Groq Qwen)
const PROVIDER_BATCH_LIMIT = 3;

if (mode === 'photo') {
  const binaryKeys = Object.keys(binaryData);
  const imageCount = binaryKeys.length;

  if (imageCount === 0) {
    return [{
      json: {
        is_error: true,
        error: {
          code: 'INVALID_INPUT',
          message: 'Setidaknya satu foto label harus disediakan.',
          retryable: false
        }
      }
    }];
  }

  if (imageCount > MAX_PRODUCT_IMAGES) {
    return [{
      json: {
        is_error: true,
        error: {
          code: 'TOO_MANY_IMAGES',
          message: `Maksimal ${MAX_PRODUCT_IMAGES} foto per sesi analisis. Ditemukan ${imageCount} foto.`,
          retryable: false
        }
      }
    }];
  }

  // Prepare batches according to PROVIDER_BATCH_LIMIT
  const batches = [];
  for (let i = 0; i < imageCount; i += PROVIDER_BATCH_LIMIT) {
    const batchKeys = binaryKeys.slice(i, i + PROVIDER_BATCH_LIMIT);
    const imageContents = batchKeys.map(k => {
      const file = binaryData[k];
      return {
        type: 'image_url',
        image_url: {
          url: `data:${file.mimeType || 'image/jpeg'};base64,${file.data}`
        }
      };
    });
    batches.push(imageContents);
  }

  return [{
    json: {
      mode: 'photo',
      image_count: imageCount,
      batch_count: batches.length,
      batches: batches,
      session_id: `nutri_${Date.now()}`,
      is_error: false
    }
  }];
} else if (mode === 'text') {
  const labelText = body.text || '';
  if (!labelText.trim()) {
    return [{
      json: {
        is_error: true,
        error: {
          code: 'INVALID_INPUT',
          message: 'Teks label tidak boleh kosong.',
          retryable: false
        }
      }
    }];
  }

  return [{
    json: {
      mode: 'text',
      text: labelText,
      session_id: `nutri_${Date.now()}`,
      is_error: false
    }
  }];
} else if (mode === 'manual') {
  let manualData = body.manual;
  if (typeof manualData === 'string') {
    try { manualData = JSON.parse(manualData); } catch (e) {}
  }
  return [{
    json: {
      mode: 'manual',
      manual: manualData || {},
      session_id: `nutri_${Date.now()}`,
      is_error: false
    }
  }];
}

return [{
  json: {
    is_error: true,
    error: {
      code: 'INVALID_INPUT',
      message: 'Mode input tidak dikenali (harus photo, text, atau manual).',
      retryable: false
    }
  }
}];

// Prepare AI Payload for Groq Multimodal / Text Extraction
const data = $input.item.json;
const mode = data.mode;

const systemPrompt = `Anda adalah asisten ekstraksi data fakta label kemasan makanan/minuman yang sangat teliti, netral, dan patuh pada prinsip 'Facts, not verdicts'.

TUGAS:
Ekstrak seluruh informasi yang terlihat pada label ke dalam format JSON tunggal sesuai skema.

ATURAN MUTLAK:
1. Ekstrak HANYA informasi yang terlihat atau terbaca secara eksplisit.
2. JANGAN PERNAH mengarang, menebak, atau menambahkan informasi yang tidak ada. Jika suatu nilai (misal gula, natrium, takaran saji) tidak tertera di label, kembalikan null.
3. JANGAN memberikan penilaian kesehatan, skor nutrisi, atau kata 'sehat' / 'tidak sehat'.
4. Jangan melakukan perhitungan aritmatika; salin angka dan unit persis sebagaimana tertulis di label.
5. Pisahkan deklarasi alergen eksplisit (misal 'Mengandung alergen: susu') dari sekadar penyebutan bahan di komposisi.
6. Catat daftar 'missing_information' jika ada elemen penting yang tidak ditemukan pada label.

SKEMA JSON HARUS PERSIS SEPERTI INI:
{
  "identity": {
    "name": string | null,
    "brand": string | null,
    "category": string | null
  },
  "serving": {
    "size": number | null,
    "unit": string | null,
    "servings_per_container": number | null,
    "basis": "per_serving" | "per_100g" | "per_100ml" | "per_package" | null
  },
  "nutrition": {
    "energy": number | null,
    "protein": number | null,
    "total_fat": number | null,
    "saturated_fat": number | null,
    "carbohydrate": number | null,
    "sugar": number | null,
    "sodium": number | null,
    "additional": []
  },
  "ingredients": {
    "raw_text": string | null,
    "items": [
      {
        "name": string,
        "role": string | null,
        "description": string | null
      }
    ]
  },
  "allergens": {
    "explicit_declaration": string | null,
    "items": []
  },
  "missing_information": string[],
  "conflicts": []
}`;

if (mode === 'photo') {
  // For first batch of images
  const firstBatch = data.batches[0];
  const messages = [
    { role: 'system', content: systemPrompt },
    {
      role: 'user',
      content: [
        { type: 'text', text: 'Ekstrak tabel nilai gizi dan komposisi dari foto-foto label ini ke format JSON.' },
        ...firstBatch
      ]
    }
  ];

  return [{
    json: {
      ...data,
      groq_payload: {
        model: 'qwen/qwen3.6-27b',
        messages: messages,
        response_format: { type: 'json_object' },
        temperature: 0.1
      }
    }
  }];
} else if (mode === 'text') {
  const messages = [
    { role: 'system', content: systemPrompt },
    {
      role: 'user',
      content: `Ekstrak data gizi dan komposisi dari teks label berikut:\n\n${data.text}`
    }
  ];
  return [{
    json: {
      ...data,
      groq_payload: {
        model: 'qwen/qwen3.6-27b',
        messages: messages,
        response_format: { type: 'json_object' },
        temperature: 0.1
      }
    }
  }];
} else {
  // Manual mode
  return [{
    json: {
      ...data,
      extraction: data.manual
    }
  }];
}

// NutriScanner — Schema Validation & Deterministic Calculation Engine
let rawExtraction = {};
const inputData = $input.item.json;

if (inputData.mode === 'manual') {
  rawExtraction = inputData.extraction || {};
} else {
  try {
    const responseContent = inputData.choices?.[0]?.message?.content || '{}';
    rawExtraction = JSON.parse(responseContent);
  } catch (err) {
    rawExtraction = {
      identity: { name: null, brand: null },
      serving: { size: null, unit: 'g', servings_per_container: null },
      nutrition: { energy: null, protein: null, total_fat: null, saturated_fat: null, carbohydrate: null, sugar: null, sodium: null },
      ingredients: { raw_text: null, items: [] },
      allergens: { explicit_declaration: null },
      missing_information: ['Gagal melakukan parsing JSON ekstraksi AI.'],
      conflicts: []
    };
  }
}

// Ensure default structures
const identity = rawExtraction.identity || {};
const serving = rawExtraction.serving || {};
const nutrition = rawExtraction.nutrition || {};
const ingredients = rawExtraction.ingredients || {};
const allergens = rawExtraction.allergens || {};
const missingInfo = rawExtraction.missing_information || [];
const conflicts = rawExtraction.conflicts || [];

// Deterministic Calculation Engine
// Rule: Package Total = Nutrient Amount per Serving * Servings per Container
// Only calculated when both values are non-null positive numbers
const servingsCount = (serving.servings_per_container && typeof serving.servings_per_container === 'number' && serving.servings_per_container > 0)
  ? serving.servings_per_container
  : null;

const calculatedPackage = {};
const canCalculatePackage = servingsCount !== null;

const standardNutrients = ['energy', 'protein', 'total_fat', 'saturated_fat', 'carbohydrate', 'sugar', 'sodium'];

for (const nutrient of standardNutrients) {
  const val = nutrition[nutrient];
  if (typeof val === 'number' && canCalculatePackage) {
    // Deterministic calculation
    calculatedPackage[nutrient] = Math.round((val * servingsCount) * 100) / 100;
  } else {
    calculatedPackage[nutrient] = null;
  }
}

// Unit normalization (if energy is in kJ and kcal is missing, 1 kJ = 0.239006 kcal)
if (nutrition.energy_kj && !nutrition.energy) {
  nutrition.energy = Math.round(nutrition.energy_kj * 0.239006);
  nutrition.energy_unit = 'kkal';
}

if (!canCalculatePackage) {
  missingInfo.push('Jumlah sajian per kemasan tidak tersedia di label; kalkulasi total per kemasan ditiadakan.');
}

const canonicalResult = {
  session_id: inputData.session_id || `nutri_${Date.now()}`,
  status: 'review_required',
  extraction: {
    identity: {
      name: identity.name || null,
      brand: identity.brand || null,
      category: identity.category || null
    },
    serving: {
      size: typeof serving.size === 'number' ? serving.size : null,
      unit: serving.unit || 'g',
      servings_per_container: servingsCount,
      basis: serving.basis || 'per_serving'
    },
    nutrition: {
      energy: typeof nutrition.energy === 'number' ? nutrition.energy : null,
      protein: typeof nutrition.protein === 'number' ? nutrition.protein : null,
      total_fat: typeof nutrition.total_fat === 'number' ? nutrition.total_fat : null,
      saturated_fat: typeof nutrition.saturated_fat === 'number' ? nutrition.saturated_fat : null,
      carbohydrate: typeof nutrition.carbohydrate === 'number' ? nutrition.carbohydrate : null,
      sugar: typeof nutrition.sugar === 'number' ? nutrition.sugar : null,
      sodium: typeof nutrition.sodium === 'number' ? nutrition.sodium : null,
      additional: nutrition.additional || []
    },
    calculated: {
      package: calculatedPackage,
      can_calculate_package: canCalculatePackage
    },
    ingredients: {
      raw_text: ingredients.raw_text || null,
      items: ingredients.items || []
    },
    allergens: {
      explicit_declaration: allergens.explicit_declaration || null,
      items: allergens.items || []
    },
    missing_information: missingInfo,
    conflicts: conflicts
  }
};

return [{
  json: canonicalResult
}];
